//! The asset fixtures of `tests/assets` (`spec/assets.md` section 7, decision 0058): a supported
//! project built from explicit data, and one failing project per row of the static GLB profile
//! and per declaration rule, each with its exact diagnostics.
//!
//! The files are generated by `tests/assets/tools/make-glb.mjs`; this test reads them.
//! `MTEK_BLESS=1 cargo test -p mtek-compiler --test assets` rewrites the expectations (review the
//! diff).

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::fs;
use std::path::{Path, PathBuf};

use mtek_compiler::diagnostics::{Code, Diagnostic};
use mtek_compiler::project::ProjectRoot;
use mtek_compiler::source::{Fs, MemFs, ProjectPath, SourceMap};
use mtek_compiler::types::ConstValue;
use mtek_compiler::{BuildMode, CompileOptions, Inspect, InspectFormat, analyze, build, inspect};
use serde_json::{Map, Value, json};

const EXPECTED: &str = "expected.diag.json";

fn assets_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/assets")
}

fn blessing() -> bool {
    std::env::var("MTEK_BLESS").is_ok_and(|value| value == "1")
}

fn names(suite: &str) -> Vec<String> {
    let mut names: Vec<String> = fs::read_dir(assets_dir().join(suite))
        .unwrap()
        .filter_map(|entry| {
            let entry = entry.ok()?;
            entry
                .file_type()
                .ok()?
                .is_dir()
                .then(|| entry.file_name().into_string().ok())?
        })
        .collect();
    names.sort();
    names
}

fn collect(root: &Path, dir: &Path, out: &mut Vec<(String, Vec<u8>)>) {
    let mut entries: Vec<PathBuf> = fs::read_dir(dir)
        .unwrap()
        .map(|entry| entry.unwrap().path())
        .collect();
    entries.sort();
    for path in entries {
        if path.is_dir() {
            collect(root, &path, out);
            continue;
        }
        let relative = path
            .strip_prefix(root)
            .unwrap()
            .components()
            .map(|c| c.as_os_str().to_str().unwrap().to_owned())
            .collect::<Vec<_>>()
            .join("/");
        if relative != EXPECTED {
            out.push((relative, fs::read(&path).unwrap()));
        }
    }
}

fn project_fs(suite: &str, name: &str, shuffle: Option<u64>) -> MemFs {
    let root = assets_dir().join(suite).join(name);
    let mut files = Vec::new();
    collect(&root, &root, &mut files);
    let mut memory = match shuffle {
        Some(seed) => MemFs::new().with_shuffled_listing(seed),
        None => MemFs::new(),
    };
    for (path, bytes) in files {
        memory.insert(ProjectPath::new(&path).unwrap(), bytes);
    }
    memory
}

fn path_of(sources: &SourceMap, diagnostic: &Diagnostic) -> Value {
    diagnostic
        .primary
        .as_ref()
        .and_then(|label| sources.get(label.span.file))
        .map_or(Value::Null, |source| source.path().as_str().into())
}

/// The diagnostics as a stable JSON list: code, location, message, notes and suggested edits.
fn diagnostics_json(sources: &SourceMap, diagnostics: &[Diagnostic]) -> String {
    let items: Vec<Value> = diagnostics
        .iter()
        .map(|d| {
            let mut object = Map::new();
            object.insert("code".into(), d.code.as_str().into());
            let span = d.primary.as_ref().map(|label| label.span);
            object.insert("file".into(), path_of(sources, d));
            object.insert(
                "startByte".into(),
                span.map_or(Value::Null, |s| s.start.into()),
            );
            object.insert("endByte".into(), span.map_or(Value::Null, |s| s.end.into()));
            object.insert("message".into(), d.message.as_str().into());
            if !d.notes.is_empty() {
                object.insert("notes".into(), d.notes.clone().into());
            }
            if !d.edits.is_empty() {
                let edits: Vec<Value> = d
                    .edits
                    .iter()
                    .map(|edit| {
                        json!({
                            "description": edit.description,
                            "edits": edit.edits.iter().map(|e| json!({
                                "startByte": e.span.start,
                                "endByte": e.span.end,
                                "replacement": e.replacement,
                            })).collect::<Vec<_>>(),
                        })
                    })
                    .collect();
                object.insert("suggestedEdits".into(), edits.into());
            }
            Value::Object(object)
        })
        .collect();
    let mut text = serde_json::to_string_pretty(&Value::Array(items)).unwrap();
    text.push('\n');
    text
}

fn build_project(suite: &str, name: &str) -> mtek_compiler::BuildResult {
    build(
        &ProjectRoot::at_base(),
        &project_fs(suite, name, None),
        &CompileOptions::with_stub_runtime(BuildMode::Release),
    )
}

#[test]
fn authored_vertex_reads_require_asset_attributes_even_when_fragment_is_constant() {
    // Keep the generated GLB unchanged and probe an independent vertex-only UV read.
    let mut files = project_fs("fail", "e7010_mesh_lacks_uv", None);
    files.insert(
        ProjectPath::new("src/main.mtek").unwrap(),
        br#"
const CHAIR = asset.glb("../models/chair.glb");
material Move {
    vertex(input: VertexInput) -> vec3 { return input.position + vec3(input.uv, 0.0); }
    fragment(input: SurfaceInput) -> color { return #ffffff; }
}
scene Demo {
    camera Main {}
    entity Wedge { mesh: CHAIR.mesh("Wedge"); material: Move {}; }
}
"#
        .to_vec(),
    );
    let result = analyze(&ProjectRoot::at_base(), &files);
    let errors: Vec<_> = result
        .report
        .diagnostics
        .iter()
        .filter(|d| d.severity == mtek_compiler::diagnostics::Severity::Error)
        .collect();
    assert_eq!(errors.len(), 1, "{:#?}", result.report);
    assert_eq!(errors[0].code, Code::E7010);
    assert!(errors[0].message.contains("TEXCOORD_0"));
}

#[test]
fn imported_vertex_outputs_can_supply_missing_asset_uvs_and_normals() {
    let mut files = project_fs("fail", "e7010_mesh_lacks_uv", None);
    files.insert(
        ProjectPath::new("src/main.mtek").unwrap(),
        br#"
import { Generated } from "./generated.mtek";
const CHAIR = asset.glb("../models/chair.glb");
scene Demo {
    camera Main {}
    entity Wedge { mesh: CHAIR.mesh("Wedge"); material: Generated {}; }
}
"#
        .to_vec(),
    );
    files.insert(ProjectPath::new("src/generated.mtek").unwrap(), br#"
struct GeneratedVertex { position: vec3; normal: vec3; uv: vec2; }
export material Generated {
    vertex(input: VertexInput) -> GeneratedVertex {
        return GeneratedVertex { position: input.position; normal: vec3(0.0, 1.0, 0.0); uv: vec2(0.5) };
    }
    fragment(surface: SurfaceInput) -> color {
        return lighting.pbr(surface, color.linear(vec3(surface.uv, 0.0), 1.0), 0.0, 0.5);
    }
}
"#.to_vec());
    let result = build(
        &ProjectRoot::at_base(),
        &files,
        &CompileOptions::with_stub_runtime(BuildMode::Release),
    );
    assert!(!result.has_errors(), "{:#?}", result.report);
    let shaders: Vec<_> = result
        .files
        .iter()
        .filter(|(path, _)| path.ends_with(".wgsl"))
        .collect();
    assert!(!shaders.is_empty());
}

#[test]
fn every_failing_project_reports_exactly_its_diagnostics() {
    let names = names("fail");
    assert!(names.len() >= 60, "fixtures are missing: {names:?}");
    for name in &names {
        let result = build_project("fail", name);
        assert!(
            result.has_errors(),
            "assets/fail/{name} reports no error: {}",
            diagnostics_json(&result.sources, &result.report.diagnostics)
        );
        assert!(result.files.is_empty(), "assets/fail/{name} produced files");
        let actual = diagnostics_json(&result.sources, &result.report.diagnostics);
        let path = assets_dir().join("fail").join(name).join(EXPECTED);
        if blessing() {
            fs::write(&path, &actual).unwrap();
            continue;
        }
        let expected = fs::read_to_string(&path).unwrap_or_else(|e| {
            panic!(
                "missing {} ({e}); run MTEK_BLESS=1 and review it",
                path.display()
            )
        });
        assert_eq!(
            expected, actual,
            "assets/fail/{name}: if the change is intended run `MTEK_BLESS=1 cargo test -p mtek-compiler --test assets` and review the diff"
        );
    }
}

#[test]
fn every_failing_project_is_checked_the_same_way_by_check_and_by_build() {
    // `check` stops after the front end; every fixture's diagnostics come from there, except
    // the packaged-size limit, which only `build` computes.
    for name in names("fail") {
        if name == "e7026_total_bytes" {
            continue;
        }
        let checked = analyze(&ProjectRoot::at_base(), &project_fs("fail", &name, None));
        let built = build_project("fail", &name);
        let sources = checked.project.as_ref().map(|p| p.sources.clone()).unwrap();
        assert_eq!(
            diagnostics_json(&sources, &checked.report.diagnostics),
            diagnostics_json(&built.sources, &built.report.diagnostics),
            "{name}"
        );
    }
}

#[test]
fn every_catalogue_code_of_the_profile_has_a_failing_project() {
    let mut seen = std::collections::BTreeSet::new();
    for name in names("fail") {
        let text = fs::read_to_string(assets_dir().join("fail").join(&name).join(EXPECTED))
            .unwrap_or_default();
        let items: Vec<Value> = serde_json::from_str(&text).unwrap_or_default();
        for item in items {
            if let Some(code) = item.get("code").and_then(Value::as_str) {
                seen.insert(code.to_owned());
            }
        }
    }
    for code in Code::ALL {
        let short = code.short();
        let asset = short.starts_with("E70") || short.starts_with("E79");
        // E7030 and E7031 are produced by the runtime (task M4-06).
        if !asset || matches!(short, "E7030" | "E7031") {
            continue;
        }
        assert!(
            seen.contains(code.as_str()),
            "no tests/assets/fail project produces {short}"
        );
    }
}

#[test]
fn the_failing_projects_are_deterministic_for_any_directory_order() {
    for name in names("fail") {
        let reference = build_project("fail", &name);
        let first = diagnostics_json(&reference.sources, &reference.report.diagnostics);
        for seed in [1, 2] {
            let result = build(
                &ProjectRoot::at_base(),
                &project_fs("fail", &name, Some(seed)),
                &CompileOptions::with_stub_runtime(BuildMode::Release),
            );
            assert_eq!(
                first,
                diagnostics_json(&result.sources, &result.report.diagnostics),
                "{name} with seed {seed}"
            );
        }
    }
}

